import { TweenLite } from 'gsap';
import { Container, FederatedPointerEvent, Graphics, Sprite, Texture } from 'pixi.js';

import { Slide } from './base-slide';
import { SliderControl } from './slider-control';

export const BASE_HEIGHT = 640;
export const BASE_WIDTH = 1136;

export class SlideManager extends Container {
    protected slides: Slide[];
    protected currentSlideIndex: number;
    protected controlsContainer: Container;
    protected slideMask: Graphics;
    protected slideOutPosition: number = 0;
    protected slideInPosition: number = 0;
    protected swipeRegion: Sprite;
    protected swipeThreshold: number;
    protected slideWidth: number;
    protected slideHeight: number;
    protected slideInTween!: TweenLite;
    private autoPlayTransitionDuration: number;
    private transitionDuration: number;
    private pointerCoords: number;

    constructor(slides: Slide[], slideControlAssets: {enabled: Texture, disabled: Texture}, dimensions: { width: number, height: number }) {
        super();

        this.slides = slides;
        this.controlsContainer = new Container();

        this.currentSlideIndex = 0;
        this.pointerCoords = 0;
        this.autoPlayTransitionDuration = 1.5;
        this.transitionDuration = 0.5;
        this.swipeThreshold = 100;

        this.slideMask = new Graphics();

        const graphic = new Graphics();
        graphic.beginFill(0x000000, 0);
        graphic.drawRoundedRect(0, 0, 100, 100, 10);
        graphic.endFill();
        const texture = window.$pixi.renderer.generateTexture({ target: graphic });

        this.swipeRegion = new Sprite(texture);
        this.swipeRegion.interactive = true;

        this.interactive = true;

        this.onPointerDown = this.onPointerDown.bind(this);
        this.onPointerMove = this.onPointerMove.bind(this);
        this.onPointerUp = this.onPointerUp.bind(this);
        this.transitionSlideLeft = this.transitionSlideLeft.bind(this);
        this.transitionSlideRight = this.transitionSlideRight.bind(this);
        this.transitionSlideIn = this.transitionSlideIn.bind(this);
        this.changeSlide = this.changeSlide.bind(this);

        this.swipeRegion.on('pointerdown', this.onPointerDown);

        this.slideWidth = dimensions.width;
        this.slideHeight = dimensions.height;

        (this.slides as Slide[]).forEach((slide, index) => {
            const enabled = index === 0;

            slide.setCallbacks(this.transitionSlideIn, this.transitionSlideLeft, index);

            const control = new SliderControl(slideControlAssets, enabled, this.changeSlide, this.transitionSlideIn, index);
            this.controlsContainer.addChild(control);
        });
    }

    public handleOrientationChange(viewportWidth: number, viewportHeight: number): void {
        const halfViewportWidth = viewportWidth * 0.5;
        const heightScale = viewportHeight / BASE_HEIGHT;
        const widthScale = viewportWidth / BASE_WIDTH;

        const scale = (heightScale > widthScale ? widthScale : heightScale);

        this.swipeRegion.width = viewportWidth;
        this.swipeRegion.height = viewportHeight;

        this.slideWidth = BASE_WIDTH;
        this.slideHeight = BASE_HEIGHT * 0.5;

        this.slideOutPosition = viewportWidth * 2;
        this.slideInPosition = halfViewportWidth;

        (this.controlsContainer.children as SliderControl[]).forEach((control) => {
            control.handleOrientationChange(BASE_HEIGHT * 0.1);
        });

        this.controlsContainer.scale.set(scale);
        this.controlsContainer.position.x = halfViewportWidth - (this.controlsContainer.width * 0.5);
        this.controlsContainer.position.y = viewportHeight - (this.controlsContainer.height * 1.2);

        const controlsHeight = this.controlsContainer.height * 1.2;
        const availableHeight = viewportHeight - controlsHeight;
        const slideYPosition = availableHeight * 0.5;

        this.slides.forEach((slide) => {
            slide.handleOrientationChange(this.slideWidth, this.slideHeight, slideYPosition);
            slide.position.x = this.slideOutPosition;
        });

        this.swipeThreshold = this.slides[this.currentSlideIndex].width * 0.15;

        this.slides[this.currentSlideIndex].position.x = this.slideInPosition;
    }

    public destroy(): void {
        this.swipeRegion.off('pointerdown', this.onPointerDown);
        super.destroy();
    }

    protected addChildren(): void {
        // Should be overriden in the game.
        // Adds the children to the stage in the desired order so that any interactivity works correctly
        // in addition to being visually layered correctly.
    }

    protected transitionSlideLeft(isAutoPlayTransition: boolean = false, goToLastSlide: boolean = false, newSlideIndex?: number): void {
        let slideIndex = newSlideIndex !== undefined ? newSlideIndex : this.currentSlideIndex === this.slides.length - 1 ? 0 : this.currentSlideIndex + 1;
        const duration = isAutoPlayTransition ? this.autoPlayTransitionDuration : this.transitionDuration;

        if (goToLastSlide) {
            slideIndex = this.slides.length - 1;
        }

        this.slides[slideIndex].position.x = this.slideOutPosition;

        TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: -this.slideOutPosition
        });

        this.currentSlideIndex = slideIndex;
    }

    protected transitionSlideRight(isAutoPlayTransition: boolean = false, goToFirstSlide: boolean = false, newSlideIndex?: number): void {
        let slideIndex = newSlideIndex !== undefined ? newSlideIndex : this.currentSlideIndex === 0 ? this.slides.length - 1 : this.currentSlideIndex - 1;
        const duration = isAutoPlayTransition ? this.autoPlayTransitionDuration : this.transitionDuration;

        if (goToFirstSlide) {
            slideIndex = 0;
        }

        this.slides[slideIndex].position.x = -this.slideOutPosition;

        TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: this.slideOutPosition
        });

        this.currentSlideIndex = slideIndex;
    }

    protected onSlideInFinished(): void {
        // no implementation
    }

    protected applyMask(xPosition: number, yPosition: number, width: number, height: number): Graphics {
        this.slideMask.clear();
        this.slideMask.beginFill(0x000000, 0);
        this.slideMask.drawRect(xPosition, yPosition, width, height);
        this.slideMask.endFill();

        return this.slideMask;
    }

    protected transitionSlideIn(isAutoPlayTransition: boolean = false): void {
        const duration = isAutoPlayTransition ? this.autoPlayTransitionDuration : this.transitionDuration;

        this.updateControls();

        this.slideInTween = TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: this.slideInPosition,
            onComplete: this.onSlideInFinished.bind(this)
        });
    }

    private changeSlide(slideIndex: number): void {
        if (this.currentSlideIndex === 0 && slideIndex === this.slides.length - 1) {
            if (this.slides.length > 2) {
                this.transitionSlideRight();
            } else {
                this.transitionSlideLeft();
            }
        } else if (this.currentSlideIndex === this.slides.length - 1 && slideIndex === 0) {
            if (this.slides.length > 2) {
                this.transitionSlideLeft();
            } else {
                this.transitionSlideRight();
            }
        } else if (slideIndex < this.currentSlideIndex) {
            this.transitionSlideRight(false, false, slideIndex);
        } else {
            this.transitionSlideLeft(false, false, slideIndex);
        }
    }

    private updateControls(): void {
        const controlsContainer = (this.controlsContainer.children as SliderControl[]);
        controlsContainer.forEach((control) => {
            control.disable();
        });

        controlsContainer[this.currentSlideIndex].enable();
    }

    private onPointerDown(e: FederatedPointerEvent): void {
        this.pointerCoords = e.data.global.x;

        this.swipeRegion.on('pointerup', this.onPointerUp);
        this.swipeRegion.on('pointerout', this.onPointerUp);
        this.swipeRegion.on('pointermove', this.onPointerMove);
        this.swipeRegion.on('pointerupoutside', this.onPointerUp);
    }

    private onPointerMove(e: FederatedPointerEvent): void {
        this.slides[this.currentSlideIndex].position.x = (e.data.global.x - this.pointerCoords) + this.slideInPosition;
    }

    private onPointerUp(): void {
        const distance = this.slides[this.currentSlideIndex].position.x - this.slideInPosition;
        if (distance > this.swipeThreshold || distance < -this.swipeThreshold) {
            if (this.slides[this.currentSlideIndex].position.x > this.slideInPosition) {
                this.transitionSlideRight();
            } else {
                this.transitionSlideLeft();
            }
        }

        this.swipeRegion.off('pointermove', this.onPointerMove);
        this.swipeRegion.off('pointerup', this.onPointerUp);
        this.swipeRegion.off('pointerout', this.onPointerUp);
        this.swipeRegion.off('pointerupoutside', this.onPointerUp);

        this.transitionSlideIn();

        this.pointerCoords = 0;
    }
}
